create extension if not exists pgcrypto;
create type public.app_role as enum ('admin','jefatura_comercial','ejecutivo_comercial','consulta');
create table public.organizations(id uuid primary key default gen_random_uuid(),nombre text not null,razon_social text,rut text,correo text,telefono text,direccion text,comuna text,ciudad text,region text,zona_horaria text not null default 'America/Santiago',moneda text not null default 'CLP',estado text not null default 'activo',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,organization_id uuid not null references organizations(id),nombre text not null,apellido text not null default '',correo text not null,telefono text,rol app_role not null default 'ejecutivo_comercial',cargo text,estado text not null default 'activo',avatar_url text,google_calendar_connected boolean not null default false,last_login_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.empresas(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),razon_social text not null,nombre_fantasia text,rut text,giro text,pagina_web text,direccion text,comuna text,ciudad text,region text,segmento text,origen text,ejecutivo_responsable_id uuid references profiles(id),observaciones text,estado text not null default 'activo',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table public.contactos(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),empresa_id uuid references empresas(id),nombre text not null,apellido text,cargo text,telefono text,telefono_normalizado text,whatsapp text,correo text,correo_normalizado text,direccion text,comuna text,ciudad text,region text,tipo_contacto text,preferencia_contacto text,origen text,estado text default 'activo',ejecutivo_responsable_id uuid references profiles(id),consentimiento_comunicaciones boolean default false,observaciones text,created_at timestamptz default now(),updated_at timestamptz default now(),deleted_at timestamptz);
create table public.proyectos(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),nombre text not null,empresa_id uuid references empresas(id),contacto_principal_id uuid references contactos(id),direccion text,comuna text,ciudad text,region text,tipo_proyecto text,tipo_obra text,obra_nueva_o_existente text,metros_cuadrados_estimados numeric(12,2),descripcion text,estado text default 'activo',ejecutivo_responsable_id uuid references profiles(id),created_at timestamptz default now(),updated_at timestamptz default now());
create table public.oportunidades(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),contacto_id uuid not null references contactos(id),empresa_id uuid references empresas(id),proyecto_id uuid references proyectos(id),nombre text not null,monto_estimado bigint not null default 0,probabilidad_cierre int check(probabilidad_cierre between 0 and 100),etapa_comercial text not null,temperatura text,prioridad text,fecha_estimada_cierre date,ejecutivo_responsable_id uuid references profiles(id),motivo_perdida text,ultima_actividad_at timestamptz,proxima_accion text,fecha_proxima_accion timestamptz,estado text default 'abierta',created_at timestamptz default now(),updated_at timestamptz default now(),closed_at timestamptz);
create table public.cotizaciones(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),numero_cotizacion text not null,numero_cotizacion_normalizado text not null,oportunidad_id uuid not null references oportunidades(id),proyecto_id uuid references proyectos(id),contacto_id uuid not null references contactos(id),empresa_id uuid references empresas(id),version_documento int not null default 1,fecha_emision date not null,fecha_validez date,estado text not null,subtotal_neto bigint not null default 0,descuento_total bigint not null default 0,neto_afecto bigint not null default 0,neto_exento bigint not null default 0,iva bigint not null default 0,total bigint not null default 0,moneda text not null default 'CLP',archivo_pdf_url text,ejecutivo_responsable_id uuid not null references profiles(id),fecha_proximo_seguimiento timestamptz,proxima_accion text,nota_comercial text,origen_registro text not null default 'manual',import_batch_id uuid,created_by uuid references profiles(id),created_at timestamptz default now(),updated_at timestamptz default now(),deleted_at timestamptz,constraint cotizacion_numero_unico unique(organization_id,numero_cotizacion_normalizado),constraint cotizacion_numero_no_vacio check(length(trim(numero_cotizacion))>0));
create table public.audit_logs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),usuario_id uuid,entidad_tipo text not null,entidad_id uuid not null,accion text not null,valores_anteriores jsonb,valores_nuevos jsonb,direccion_ip inet,user_agent text,created_at timestamptz default now());
create or replace function public.current_org() returns uuid language sql stable security definer set search_path=public as $$select organization_id from profiles where id=auth.uid()$$;
create or replace function public.current_role() returns app_role language sql stable security definer set search_path=public as $$select rol from profiles where id=auth.uid()$$;
alter table organizations enable row level security;alter table profiles enable row level security;alter table empresas enable row level security;alter table contactos enable row level security;alter table proyectos enable row level security;alter table oportunidades enable row level security;alter table cotizaciones enable row level security;alter table audit_logs enable row level security;
create policy org_read on organizations for select using(id=current_org());create policy profile_org on profiles for select using(organization_id=current_org());
create policy empresa_org on empresas for all using(organization_id=current_org()) with check(organization_id=current_org());create policy contacto_org on contactos for all using(organization_id=current_org()) with check(organization_id=current_org());create policy proyecto_org on proyectos for all using(organization_id=current_org()) with check(organization_id=current_org());create policy oportunidad_org on oportunidades for all using(organization_id=current_org()) with check(organization_id=current_org());create policy cotizacion_read on cotizaciones for select using(organization_id=current_org());create policy cotizacion_write on cotizaciones for all using(organization_id=current_org() and current_role()<> 'consulta') with check(organization_id=current_org() and current_role()<> 'consulta');create policy audit_admin on audit_logs for select using(organization_id=current_org() and current_role()='admin');
